insert into public.care_assignments(patient_id,professional_id,specialty,starts_at,created_by)values('d2000000-0000-4000-8000-000000000001','d1000000-0000-4000-8000-000000000007','direction',now()-interval '1 day','d1000000-0000-4000-8000-000000000006');
