insert into public.care_intervention_requests(id,record_id,patient_id,source_revision,requested_by,body)values('d6000000-0000-4000-8000-000000000001','d4000000-0000-4000-8000-000000000002','d2000000-0000-4000-8000-000000000001',1,'d1000000-0000-4000-8000-000000000004','Solicitud neutra QA');
create function pg_temp.dp(n integer,v integer default 0) returns jsonb language sql as $$select jsonb_build_object('id','d8000000-0000-4000-8000-'||lpad(n::text,12,'0'),'patient_id','d2000000-0000-4000-8000-000000000001','version',v,'situation','Situación interna QA','evaluation','Deliberación exclusiva QA','decision','Decisión interna QA','responsible_id','d1000000-0000-4000-8000-000000000006','planned_at',now()+interval '1 day','review_at',now()+interval '2 days','confirm_final',true,'reason','Enmienda interna QA','result','Resultado interno QA')$$;
