select public.care_decision_write('decision_final',pg_temp.dp(1,1)||'{"record_id":"d4000000-0000-4000-8000-000000000002","request_id":"d6000000-0000-4000-8000-000000000001"}'::jsonb);
select pg_temp.care_assert(public.care_decision_read('d8000000-0000-4000-8000-000000000001')->'decision'->>'state'='active','Final decision active');
