select pg_temp.care_assert(jsonb_array_length(public.care_supervision(30,1,'tasks')->'rows')=25,'Tasks first page 25');
select pg_temp.care_assert(jsonb_array_length(public.care_supervision(30,2,'tasks')->'rows')=9,'Tasks second page nine');
select pg_temp.care_assert((public.care_supervision(30,1,'tasks')->'summary'->>'pending')::int=30,'Counts full set not first page');
select pg_temp.care_denied($$select public.care_supervision(30,1,'tasks',null,'all','d2000000-0000-4000-8000-000000000009')$$,'Patient filter outside scope denied');
select pg_temp.care_denied($$select public.care_supervision(30,1,'tasks','d1000000-0000-4000-8000-000000000009')$$,'Professional filter outside scope denied');
select pg_temp.care_denied($$select public.care_supervision(30,0)$$,'Invalid page denied','P0001');
select pg_temp.care_denied($$select public.care_supervision(30,1,'bad')$$,'Invalid mode denied','P0001');
select pg_temp.care_denied($$select public.care_decision_list(null,0)$$,'Decision invalid page denied','P0001');
reset role;
update private.care_delegated_tasks set created_at=now()-interval '120 days' where id='d9000000-0000-4000-8000-000000000020';
set local role authenticated;
select pg_temp.care_assert((public.care_supervision(7,1,'tasks')->>'total')::int=34,'Old pending remains actionable in short period');
reset role;
update public.care_session_records set revision=2 where id='d4000000-0000-4000-8000-000000000002';
set local role authenticated;
select pg_temp.care_assert(public.care_decision_read('d8000000-0000-4000-8000-000000000001')->'decision'->>'record_revision'='1','Later source amendment cannot rewrite exact evidence');
select pg_temp.care_denied($$select public.care_decision_write('decision_final',pg_temp.dp(4)||'{"request_id":"d6000000-0000-4000-8000-000000000001"}'::jsonb)$$,'Request cannot spawn duplicate final decision','23505');
reset role;
update public.care_staff_capabilities set capabilities=array_append(capabilities,'care.family.read') where user_id in('d1000000-0000-4000-8000-000000000006','d1000000-0000-4000-8000-000000000004');
insert into public.care_events(id,title,kind,starts_at,ends_at,professional_id,modality,status,closed_at,created_by)values('d3000000-0000-4000-8000-000000000010','Familia supervisión QA','family',now()-interval '2 hours',now()-interval '1 hour','d1000000-0000-4000-8000-000000000004','in_person','completed',now(),'d1000000-0000-4000-8000-000000000004');
insert into public.care_event_participants(event_id,patient_id,attendance)values('d3000000-0000-4000-8000-000000000010','d2000000-0000-4000-8000-000000000001','absent');
set local role authenticated;
select set_config('request.jwt.claim.sub','d1000000-0000-4000-8000-000000000006',true);
select pg_temp.care_assert((select count(*)=1 from jsonb_array_elements(public.care_supervision(30,1,'records')->'rows') r where r->>'specialty'='family' and r->>'state'='pending'),'Family expected from realized session even if patient absent');
reset role;
insert into public.care_family_records(id,patient_id,event_id,author_id,occurred_at,status,revision,first_finalized_at)values('d7000000-0000-4000-8000-000000000001','d2000000-0000-4000-8000-000000000001','d3000000-0000-4000-8000-000000000010','d1000000-0000-4000-8000-000000000004',now()-interval '2 hours','final',1,now());
set local role authenticated;
select pg_temp.care_assert((select count(*)=1 from jsonb_array_elements(public.care_supervision(30,1,'records')->'rows') r where r->>'specialty'='family' and r->>'state'='completed' and r->>'record_id'='d7000000-0000-4000-8000-000000000001'),'Family final supplies original authorized record');
reset role;
update public.care_staff_capabilities set capabilities=array_remove(capabilities,'care.family.read') where user_id='d1000000-0000-4000-8000-000000000006';
set local role authenticated;
select pg_temp.care_assert((select count(*)=0 from jsonb_array_elements(public.care_supervision(30,1,'records')->'rows') r where r->>'specialty'='family'),'Family counts and sources withheld when viewer permission revoked');
select pg_temp.care_assert((public.care_supervision(30,1,'records',null,'overdue')->>'total')::int=0,'No universal record deadline after user clarification');
reset role;
rollback;
